class unfair_shared_mutex_t {
    enum state_t : std::int32_t { idle_k = 0, writing_k = -1, };
    std::atomic<std::int32_t> state_{idle_k};
  public:
    inline void lock() noexcept { /* CAS to writing */ }
    inline void unlock() noexcept { state_.store(idle_k, std::memory_order_release); }
    inline void lock_shared() noexcept { /* increment readers unless writing */ }
    inline void unlock_shared() noexcept { state_.fetch_sub(1, std::memory_order_release); }
    inline bool try_escalate() noexcept { std::int32_t one_read = 1; return state_.compare_exchange_weak(one_read, writing_k, std::memory_order_acquire, std::memory_order_relaxed); }
    inline void unsafe_escalate() noexcept { if (!try_escalate()) { unlock_shared(); lock(); } }
    inline void escalate() noexcept { while (!try_escalate()) std::this_thread::yield(); }
    inline void de_escalate() noexcept { std::int32_t one_read = 1; state_.store(one_read, std::memory_order_release); }
};

