import random
import struct
import itertools

# Generator for FUZZ_PARAM_STR payloads used across stubs to:
# - act as arbitrary text tokens (metric/scalar parsing)
# - fill numeric/vector byte buffers for f32 data
# - seed deterministic content for dataset/query/centroid buffers
#
# Requirements:
# - Return bytes (<= 4096)
# - Deterministic under seed, but still varied
# - Provide many valid and interesting cases: ASCII words for parsers,
#   structured float arrays, lengths spanning 0..~2KB, embedded NULs, etc.

_CANONICAL_STRINGS = [
    b"f32", b"f64", b"f16", b"bf16", b"i8", b"b1",
    b"l2sq", b"euclidean_sq", b"ip", b"inner", b"dot", b"cos", b"angular",
    b"haversine", b"divergence", b"pearson", b"hamming", b"tanimoto", b"sorensen", b"jaccard",
]

def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))

def _make_float_bytes(rng: random.Random, count: int, pattern: str = "mixed") -> bytes:
    vals = []
    if pattern == "zeros":
        vals = [0.0] * count
    elif pattern == "ones":
        vals = [1.0] * count
    elif pattern == "ramp":
        start = rng.uniform(-3.0, 3.0)
        step = rng.uniform(-0.5, 0.5)
        vals = [start + i * step for i in range(count)]
    elif pattern == "unit":
        # Unit vector with one 1, rest 0
        vals = [0.0] * count
        if count:
            vals[rng.randrange(count)] = 1.0
    else:
        vals = [rng.uniform(-10.0, 10.0) for _ in range(count)]
    # pack as f32 little-endian
    return struct.pack("<" + "f" * len(vals), *vals)

def _embed_nulls(rng: random.Random, data: bytes, max_inserts: int = 4) -> bytes:
    if not data:
        return data
    inserts = rng.randrange(0, max_inserts + 1)
    out = bytearray()
    idxs = sorted(rng.randrange(0, len(data) + 1) for _ in range(inserts))
    last = 0
    for idx in idxs:
        out += data[last:idx]
        out.append(0)
        last = idx
    out += data[last:]
    return bytes(out)

def _build_token_payload(rng: random.Random, budget: int) -> bytes:
    # Compose tokens, separated by random whitespace and punctuation, to feed parsers.
    tokens = []
    # Ensure at least one canonical token appears to trigger positive paths.
    tokens.append(rng.choice(_CANONICAL_STRINGS))
    # Add a few random or canonical tokens.
    for _ in range(rng.randrange(1, 6)):
        if rng.random() < 0.6:
            tokens.append(rng.choice(_CANONICAL_STRINGS))
        else:
            # random ascii-ish token of length 1..10
            L = rng.randrange(1, 11)
            tok = bytes(rng.choice(b"abcdefghijklmnopqrstuvwxyz0123456789_-") for _ in range(L))
            tokens.append(tok)
    seps = [b" ", b"\t", b"\n", b",", b";", b"|", b":" ]
    payload = b""
    for i, t in enumerate(tokens):
        payload += t
        if i + 1 < len(tokens):
            payload += rng.choice(seps) * rng.randrange(1, 3)
        if len(payload) > budget:
            break
    return payload[:budget]

def _build_vector_payload(rng: random.Random, budget: int) -> bytes:
    # Create f32 arrays for dataset/query buffers. Keep sizes modest but varied.
    # Choose a total byte length fitting within budget, prefer multiples of 4.
    if budget < 4:
        return _rand_bytes(rng, budget)
    # Pick a float count such that total bytes <= budget
    max_count = min(256, budget // 4)
    count = max(1, rng.randrange(1, max_count + 1))
    pattern = rng.choice(["mixed", "zeros", "ones", "ramp", "unit"])
    data = _make_float_bytes(rng, count, pattern)
    # Optionally append a small random tail to diversify byte content
    if rng.random() < 0.3:
        tail = _rand_bytes(rng, rng.randrange(0, min(16, budget - len(data) + 1)))
        data += tail
    return data[:budget]

def _build_structured_combo(rng: random.Random, budget: int) -> bytes:
    # Mix: header tokens + binary f32 blob, to satisfy both parser and numeric users.
    head_budget = min(budget // 3, 64)
    body_budget = budget - head_budget
    head = _build_token_payload(rng, head_budget)
    body = _build_vector_payload(rng, body_budget)
    data = head + body
    if rng.random() < 0.4:
        data = _embed_nulls(rng, data)
    return data[:budget]

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Decide a scenario for the payload based on seed
    scenario = rng.choices(
        population=["tokens", "vector", "combo", "random", "short", "long"],
        weights=[3, 3, 3, 1, 1, 1], k=1
    )[0]

    # Choose a size budget up to 2048 to stay well below global 4096 limit.
    if scenario == "short":
        budget = rng.randrange(0, 64)  # may be zero-length
    elif scenario == "long":
        budget = rng.randrange(512, 2048)
    else:
        budget = rng.randrange(16, 1024)

    if scenario == "tokens":
        data = _build_token_payload(rng, budget)
    elif scenario == "vector":
        data = _build_vector_payload(rng, budget)
    elif scenario == "combo":
        data = _build_structured_combo(rng, budget)
    elif scenario == "random":
        data = _rand_bytes(rng, budget)
    else:
        # short/long fallbacks mix a canonical token with floats to be useful broadly
        prefix = rng.choice(_CANONICAL_STRINGS)
        rest = _build_vector_payload(rng, max(0, budget - len(prefix)))
        data = (prefix + b"\n" + rest)[:budget]

    # Occasionally insert explicit NULs to test C-string comparisons and parsers
    if rng.random() < 0.35:
        data = _embed_nulls(rng, data)

    # Final cap to 4096 just in case
    return bytes(data[:4096])
